n = int(input())

def generate_carpet(k):
    if k == 0:
        return [['#']]
    else:
        smaller_carpet = generate_carpet(k - 1)
        size = len(smaller_carpet)
        new_size = size * 3
        new_carpet = [['#' for _ in range(new_size)] for _ in range(new_size)]

        for i in range(new_size):
            for j in range(new_size):
                if size <= i < 2 * size and size <= j < 2 * size:
                    new_carpet[i][j] = '.'
                else:
                    new_carpet[i][j] = smaller_carpet[i % size][j % size]

        return new_carpet

carpet = generate_carpet(n)
for row in carpet:
    print(''.join(row))
